      title: `2022年以来云南累计完成绿电交易超40亿千瓦时`,
      summary: `中新网昆明11月16日电 (记者 韩帅南)记者15日从南方电网云南电网公司获悉，2022年以来，云南省累计完成绿电交易超过40亿千瓦时。其中，2026年1至10月绿电交易电量达到14.85亿千瓦时，占累计绿电交易电量近四成。目前，云南全省绿色能源交易电量占市场化交易电量比重已经超过90%。`,
