      detail: `图为参赛队在女子组12人龙舟100米直道赛比赛中。中新社记者 张斌 摄 图为参赛队在女子组12人龙舟100米直道赛比赛中。中新社记者 张斌 摄 图为参赛队在男子组22人龙舟200米直道赛比赛中。中新社记者 张斌 摄 图为参赛队在男子组22人龙舟500米直道赛比赛中。中新社记者 张斌 摄 图为赛前参赛龙舟在江面上巡游。中新社记者 张斌 摄 图为赛前参赛龙舟在江面上巡游。中新社记者 张斌 摄 图为获得男子组总成绩第一名的顺德乐从罗浮宫队的队员们拍照留念。中新社记者 张斌 摄`,
      meaning: `本条涉及politics领域，是时事与申论的高频关注点。`,
