      title: `广东省政协原党组成员、副主席郭永航严重违纪违法被开除党籍和公职`,
      summary: `经中共中央批准，中央纪委国家监委对广东省政协原党组成员、副主席郭永航严重违纪违法问题立案审查调查，决定给予其开除党籍、开除公职处分，涉嫌犯罪问题移送司法机关。`,
