      source: `中央纪委国家监委、央视新闻`,
      detail: `中央纪委国家监委通报，经中共中央批准，对广东省政协原党组成员、副主席郭永航严重违纪违法问题立案审查调查，查明其丧失理想信念、利用职务便利为他人谋利并收受巨额财物等，决定给予开除党籍、开除公职处分，涉嫌犯罪问题移送检察机关依法审查起诉。此案是二十届五中全会强调"持之以恒推进全面从严治党"背景下，反腐败持续纵深推进的又一例证。对备考者，"双开"的纪律与法律含义、以及"移送司法"的程序衔接，是廉政常识考点。`,
      meaning: `高层违纪违法案件常态化通报，是全面从严治党"无禁区、全覆盖、零容忍"的具象化。反腐与全会主题同频共振。`,
