      title: `习近平为阿曼苏丹海赛姆举行欢迎仪式并举行会谈 建交48年来阿曼元首首次访华`,
      summary: `应国家主席习近平邀请，阿曼苏丹海赛姆于11月1日至2日对中国进行国事访问。11月2日，习近平在人民大会堂为其举行欢迎仪式并举行会谈，两国元首就双边关系与共同关心的国际地区问题深入交换意见。`,
