      title: `习近平同秘鲁总统藤森庆子就中秘建交55周年互致贺电`,
      summary: `11月2日，国家主席习近平同秘鲁总统藤森庆子互致贺电，庆祝两国建交55周年。两国元首积极评价双边关系发展，愿继续深化各领域合作。`,
