      title: `习近平对进一步做好黄河保护治理工作作出重要指示强调 持续完善大保护大协同格局`,
      summary: `中共中央总书记、国家主席、中央军委主席习近平近日对进一步做好黄河保护治理工作作出重要指示，强调持续完善大保护大协同格局，努力让这条母亲河越来越美。`,
