      title: `央行11月3日开展证券、基金、保险公司互换便利操作 31家机构申报超千亿`,
      summary: `为支持资本市场健康稳定发展，中国人民银行将于11月3日开展证券、基金、保险公司互换便利（SFISF）操作，互换期限1年、可视情展期。目前31家证券、基金公司申报需求，申请额度超1000亿元。`,
      time: "19:30",
      source: `央视新闻、中国人民银行`,
      detail: `11月2日新闻联播联播快讯披露，为支持资本市场健康稳定发展，中国人民银行将于11月3日开展证券、基金、保险公司互换便利（SFISF）操作，互换期限1年、可视情展期；目前已有31家证券、基金公司申报需求，申请额度超过1000亿元。互换便利是央行创设的资本市场维稳工具——符合条件的机构以债券、股票ETF等资产作押，从央行换入国债、央票等高流动性资产，从而提升资金获取能力，属"防患于未然"的流动性支持。`,
      meaning: `互换便利是"给机构流动性、不直接下场"的精巧设计。它托底预期而非托底指数，体现监管"精准滴灌"的思路。`,
