      title: `股票回购增持再贷款转为长期制度性安排 再贷款利率由1.25%降至1%`,
      summary: `11月2日，央行、金融监管总局、证监会召开座谈会，明确股票回购增持再贷款政策由阶段性安排转为长期制度性安排，再贷款利率由1.25%降至1%，进一步引导上市公司和股东回购增持。`,
      time: "20:00",
      source: `央视新闻、中国人民银行`,
      detail: `11月2日，中国人民银行、金融监管总局、中国证监会召开座谈会，明确股票回购增持再贷款政策由阶段性安排正式转为长期制度性安排，并将再贷款利率由1.25%下调至1%。该工具于2024年创设，引导银行向上市公司及其主要股东发放贷款用于回购和增持股票，稳定市场预期。此次"转正"并降息，意味着政策从应急式托底转向常态化制度供给，向市场传递"长期可预期"的明确信号。`,
