      title: `前三季度全国社会物流总额280万亿元 同比增长4.9%`,
      summary: `中国物流与采购联合会11月1日发布数据，前三季度全国社会物流总额280万亿元，按可比价格计算同比增长4.9%，物流运行保持恢复向好态势。`,
